import React, { Component } from 'react';
import PropTypes from "prop-types";
/**
 * 滑动切换弹出框
 *
 * 核心是通过一个栈（只存页码，不负责内容），push---右滑，pop----左滑
 */
export default class SwipeModel extends Component {


    static propTypes = {
        getEvent:PropTypes.func,
        style:PropTypes.any,
        children:PropTypes.any
    };

    constructor(props){
        super(props);
        this.state = {
            stack:[],
            type:null // leftMoving or rightMoving
        }
    }

    componentWillMount(){

        if(this.props.getEvent){
            this.props.getEvent(this.push.bind(this),this.pop.bind(this),this.clearOut.bind(this));
        }

    }

    clearOut=()=>{
        this.setState({
            stack:[],
            type:[]
        })
    }

    push=(index)=>{
        this.state.stack.push(index);
        this.setState({stack:this.state.stack,type:index > 0 ? "leftMoving" : null});
    }

    pop=()=>{
        this.setState({stack:this.state.stack,type:"rightMoving"});
    }

    render(){

        let current;
        let style = this.props.style || {};
        if(this.props.children){
            if(this.state.type){
                current = this.props.children[this.state.stack[this.state.stack.length-2]];
                style = Object.assign(style,{overflow:"hidden"});
            }
            else{
                current = this.props.children[this.state.stack[this.state.stack.length-1]];
            }
        }

        if(!current){
            return <div style={style} />;
        }

        return (
            <div className="fl-swipe-model-box" style={style}>

                <div className="fl-swipe-current-page fl-swipe-page">
                    {
                        React.cloneElement(current, {})
                    }
                </div>

                {
                    this.state.type &&
                    <div
                        className={`fl-swipe-${this.state.type}-page fl-swipe-page`}
                        onAnimationEnd={()=>{
                            if(this.state.type === "rightMoving"){
                                this.state.stack.pop();
                                this.setState({stack: this.state.stack})
                            }
                            this.setState({type:null})
                        }
                        }
                    >
                        {
                            React.cloneElement(this.props.children[this.state.stack.length-1], {})
                        }
                    </div>
                }
            </div>
        )
    }
}



