import React, { Component } from 'react'
import classNames from "classnames";
import PropTypes from "prop-types";


export default class Tag extends Component {

    static propTypes = {
        text:PropTypes.string,
        color:PropTypes.string,
        bgColor:PropTypes.string,
        bdColor:PropTypes.string,
        className:PropTypes.string,
        prefixCls:PropTypes.string,
        style:PropTypes.object,
    }

    static defaultProps = {
        text:"公盘",
        color:"#000000",
        bgColor:"#FFFFFF",
        bdColor:null,
        prefixCls:"fl",
        style:{},
    }

    render() {
        const { text, color, bgColor, bdColor, className, prefixCls,style, ...rest } = this.props;
        const classes = classNames(`${prefixCls}-tag`,`${prefixCls}-tag-default`,className);
        const _style = Object.assign({
            color,
            backgroundColor:bgColor,
            border:`1px solid ${bdColor||bgColor}`
        },style);
        return (
            <div {...rest} className={classes} style={_style} >{text}</div>
        )
    }
}



