import React, { Component } from "react";
import classnames from "classnames";
import PropTypes from "prop-types";
import { Input,Icon } from "antd";
/**
 * 房源列表封面图（具体样式可见房源列表封面图、左侧房源历史记录封面图）
 * 此房源封面图组件自适应了图片大小，且当图片地址为空或请求404时会以默认图替代
 * props:
 *      src：房源图片地址
 */
export default class Search extends Component {
	static propTypes = {
	    value: PropTypes.string,
	    placeholder: PropTypes.string,
	    onSearch: PropTypes.func,
	    onBlur: PropTypes.func,
	    onFocus: PropTypes.func,
	    className: PropTypes.string,
	    onClear: PropTypes.func,
	    icon: PropTypes.node,
	    disabled: PropTypes.bool,
	    onInput: PropTypes.func,
	    action: PropTypes.bool,
	    actionText: PropTypes.oneOfType([PropTypes.string, PropTypes.node]),
	    onAction: PropTypes.func,
	    onPressEnter: PropTypes.func,
	    prefixCls: PropTypes.string,
	    type: PropTypes.oneOf(["default", "vague", "ghost"]),
	    size: PropTypes.oneOf(["default", "large", "small"])
	};

	static defaultProps = {
	    prefixCls: "fl",
	    type: "default",
	    actionText: "取消",
	    action: false,
	    size: "default"
	};

	constructor() {
	    super();
	    this.state = {
	        isAction: false,
	        text: '',
	    };
	}
	
	componentDidMount(){
	    const {getNode} = this.props;
	    if(getNode){
	        getNode(this.searchInput);
	    }
	}
	componentWillReceiveProps(nextProps){
	    if(nextProps.value !== this.props.value){
	        this.setState({
	            text: nextProps.value
	        })
	    }
	}
	

	actionHandle = () => {
	    const { onAction } = this.props;
	    this.closeAction();
	    if(onAction) {
	        onAction();
	    }
	}
	
	closeAction = ()=>{
	    this.setState({
	        isAction: false
	    });
	}

	clearHandle = () => {
	    const { onInput, onClear } = this.props;
	    onInput && onInput('');
	    onClear && onClear();
	    this.setState({
	        text: ''
	    })
	}

	inputHandle = (e) => {
	    const { onInput } = this.props;
	    if(onInput){
	        onInput(e.target.value);
	    }
	    this.setState({
	        text: e.target.value
	    })
	}

	render() {
	    const {
	        value,
	        type,
	        actionText,
	        className,
	        prefixCls,
	        onFocus,
	        onBlur,
	        action,
	        onAction,
	        onInput,
	        suffix,
	        prefix,
	        getNode,
	        ...rest
	    } = this.props;
	    const { isAction, text } = this.state;

	    const wrapClassName = classnames(className,`${prefixCls}-search`, {
	        [`${prefixCls}-search-${type}`]: type,
	        [`${prefixCls}-search-wrap-action`]: isAction && action
	    });

	    const inputClassName = classnames(`${prefixCls}-search-input`);

	    const prefixClassName = classnames(`${prefixCls}-search-prefix`,`${prefixCls}-search-prefix-${type}`);
		
	    const suffixClassName = classnames(`${prefixCls}-search-suffix`,`${prefixCls}-search-prefix-${type}`);

	    const actionClassName = classnames(`${prefixCls}-search-action`);

	    return (
	        <div className={wrapClassName}>
	            <Input
	                ref={ref => {this.searchInput = ref}}
	                value={text}
	                className={inputClassName}
	                prefix={<Icon className={prefixClassName} type="search" />}
	                suffix={text && <Icon className={suffixClassName} type="close-circle" onClick={this.clearHandle} />}
	                onFocus={e => {
	                    if(action){
	                        this.setState({
	                            isAction: true
	                        });
	                    }
	                    if(onFocus){
	                        onFocus(e);
	                    }
	                }}
	                onInput={this.inputHandle}
	                onBlur={onBlur}
	                {...rest}
	            />
	            {action && isAction && <div onClick={this.actionHandle} className={actionClassName}>{actionText}</div>}
	        </div>
	    );
	}
}



