import React, { Component } from 'react';
import ReactDOM from 'react-dom';
import PropTypes from "prop-types";
import classNames from "classnames";
import Transition from '../transition';
import Icon from "../icon";

export default class Notice extends Component {
    constructor(props) {
        super(props)
        this.state = {
            show: false
        }
    }

    componentDidMount() {
        this.forceUpdate();
        this.startTimer()
        this.setState({ 
            show: true
        });
    }

    componentWillUnmount() {
        clearTimeout(this.timer)
    }

    onClose() {
        this.setState({ 
            show: false 
        });
        return this.props.onClose && this.props.onClose()
    }


    onEnter = (e) => {
        return this.props.onEnter && this.props.onEnter(e);
    }

    onExited = (e) => {
        return this.props.onExited && this.props.onExited(e);
    }

    getIconClasses(){
        const { prefixCls, type, } = this.props;
        return classNames(prefixCls, `${prefixCls}-notice-icon-${type}`);
    }

    startTimer() {
        if (this.props.closable) return;
        this.timer = setTimeout(() => {
            this.onClose()
        }, this.props.duration * 1000)
    }

    render() {
        const { prefixCls, transitionName, content, type, spin, zIndex } = this.props;
        const noticeBoxClasses = classNames(prefixCls, `${prefixCls}-notice`);
        const contentClasses = classNames(prefixCls, `${prefixCls}-notice-content`);
        const iconBoxClasses = classNames(prefixCls, `${prefixCls}-notice-icon-box`);
        return (<Transition name={transitionName} show={this.state.show} onExited={(e) => this.onExited(e)} onEnter={(e) => this.onEnter(e)}>
            <div className={noticeBoxClasses} style={{zIndex}}>
                <div className={iconBoxClasses}><Icon className={this.getIconClasses()} fl spin={spin} type={type} /></div>
                <div className={contentClasses}>{content}</div>
            </div>
        </Transition>)
    }
}

Notice.defaultProps = {
    prefixCls: "fl",
    type: 'success',
    transitionName: 'fade',
    duration: 1.5,
    spin:false,
    onEnter: ()=>{},
    onExited: ()=>{},
}

Notice.propTypes = {
    prefixCls: PropTypes.string,
    type: PropTypes.string,
    content: PropTypes.string,
    closable: PropTypes.bool,
    transitionName: PropTypes.string,
    onClose: PropTypes.func,
    duration: PropTypes.number,
    onEnter: PropTypes.func,
    onExited: PropTypes.func,
    spin:PropTypes.bool
}



Notice.Instance = (props) => {
    let div = document.body.querySelector(`.fl-notice-box`);
    if(!div){
        div = document.createElement('div')
        div.className = `${props.className} fl-notice-box`;
        document.body.appendChild(div);
    }

    ReactDOM.render(<Notice
        {...props}
        onExited={() => {
            ReactDOM.unmountComponentAtNode(div);
            div.parentNode.removeChild(div);
        }}
    />, div);
}



