import React, { Component } from 'react';
import PropTypes from 'prop-types';
import classNames from "classnames";
import { CSSTransition } from 'react-transition-group';
import Icon from "../icon";

const noop = ()=>{};

export default class Button extends Component {
    static propTypes = {
        size:PropTypes.oneOf(["large","default","small"]),
        type:PropTypes.oneOf(["normal","light","plain"]),
        loading:PropTypes.bool,
        disabled:PropTypes.bool,
        children:PropTypes.any,
        prefixCls:PropTypes.string,
    }

    static defaultProps = {
        size:"default",
        type:"normal",
        loading:false,
        prefixCls:"fl",
        disabled:false,
    }

    render() {
        const { prefixCls, size, type, loading, disabled, children,className,onClick, ...rest} = this.props;
        
        const classesWrap = classNames(`${prefixCls}-button-container`,className);

        const classes = classNames(`${prefixCls}`,`${prefixCls}-button`,`${prefixCls}-button-${size}`,{
            [`${prefixCls}-button-${size}-btn`]:type !== "plain",
            [`${prefixCls}-button-${type}`]:!disabled,
            [`${prefixCls}-button-${type}-disabled`]:disabled,
            [`${prefixCls}-button-loading`]:loading,
        });

        const classesTrans = classNames({
            [`${prefixCls}-button-${size}-btn`]:type !== "plain",
            [`${prefixCls}-button-${type}`]:!disabled,
            [`${prefixCls}-button-trans-border`]:true,
            [`${prefixCls}-button-${type}-disabled`]:disabled,
            [`${prefixCls}-button-trans-init`]:loading
        });

        const classesIcon = classNames(`${prefixCls}-button-rela-icon`,{
            [`${prefixCls}-button-rela-icon-${size}`]:type !== "plain",
            [`${prefixCls}-button-rela-icon-plain-${size}`]:type === "plain",
        })
        const timeout = 300;
        return (
            <div {...rest} onClick={(disabled || loading)?noop:onClick} className={classesWrap} > 
                <CSSTransition
                    in={loading}
                    timeout={timeout}
                    classNames={`${prefixCls}-button`}
                > 
                    <div className={classes}>
                        {children} 
                    </div>
                </CSSTransition>
                <CSSTransition
                    in={loading}
                    timeout={timeout}
                    classNames={`${prefixCls}-button-trans`}
                    unmountOnExit
                > 
                    <div className={`${prefixCls}-button-rela ${classesTrans}`} />
                </CSSTransition>
                <CSSTransition
                    in={loading}
                    timeout={timeout}
                    classNames={`${prefixCls}-button-trans-icon`}
                    unmountOnExit
                > 
                    <div className={`${prefixCls}-button-rela`}>
                        <Icon className={classesIcon} fl type="jiazaizhong" spin />
                    </div> 
                </CSSTransition>
            </div>
        )
    }
}



