import React, { Component } from 'react';
import ReactDOM from 'react-dom';
import { Modal as AntModal } from "antd";
import classNames from "classnames";
import PropTypes from "prop-types";

const IS_REACT_16 = !!ReactDOM.createPortal;


class ConfirmModal extends Component {

    static propTypes = {
        type: PropTypes.oneOf(["confirm", "info"]),
        prefixCls: PropTypes.string,
        visible: PropTypes.bool,
        width: PropTypes.number,
        title: PropTypes.string || PropTypes.object,
        content: PropTypes.string || PropTypes.object,
        close: PropTypes.func,
        maskClosable: PropTypes.bool,
        cancelText: PropTypes.string || PropTypes.object,
        okText: PropTypes.string || PropTypes.object,
        onOk: PropTypes.func,
        onCancel: PropTypes.func,
        className: PropTypes.string
    }

    static defaultProps = {
        type: "confirm",
        prefixCls: "fl",
        visible: false,
        width: 250,
        title: "",
        content: "",
        maskClosable: false,
        cancelText: "取消",
        okText: "确定",
        onOk: null,
        onCancel: null,
        className: ""
    }

    handleCancel = () => {
        const {onCancel, close} = this.props;
        onCancel();
        close();
    }

    handleOk = () => {
        const {onOk, close} = this.props;
        onOk();
        close();
    }

    renderFooter = () => {
        const { type, prefixCls, okText, cancelText,} = this.props;
        const confirmFooterClasses = classNames(prefixCls, `${prefixCls}-confirm-footer`);
        const confirmBtnBorderClasses = classNames(prefixCls, `${prefixCls}-confirm-btn-border`);
        const confirmBtnClasses = classNames(prefixCls, `${prefixCls}-modal-confirm-btn`);
        const cancelBtnClasses = classNames(confirmBtnClasses, `${prefixCls}-modal-cancel-btn`);
        const okBtnClasses = classNames(confirmBtnClasses, `${prefixCls}-modal-ok-btn`);

        const infoFooterClasses = classNames(prefixCls, `${prefixCls}-info-footer`);
        const infoBtnClasses = classNames(prefixCls, `${prefixCls}-modal-info-btn`);
        
        if(type==="confirm"){
            return  <div className={confirmFooterClasses}>
                <div onClick={this.handleCancel} className={cancelBtnClasses} >{cancelText}</div>
                <div className={confirmBtnBorderClasses} />
                <div onClick={this.handleOk} className={okBtnClasses} >{okText}</div>
            </div>
        }
        return  <div className={infoFooterClasses}>
            <div onClick={this.handleOk} className={infoBtnClasses} >{okText}</div>
        </div>    
    }

    render() {
        const { type, prefixCls, visible, width, title, content, close, 
            okText, cancelText, maskClosable, onOk, onCancel, className, ...rest} = this.props;

        const confirmModalClasses = classNames(prefixCls, `${prefixCls}-confirm`, className);
        const confirmBodyClasses = classNames(prefixCls, `${prefixCls}-confirm-body`);
        const confirmTitleClasses = classNames(prefixCls, `${prefixCls}-confirm-title`);
        const confirmContentClasses = classNames(prefixCls, `${prefixCls}-confirm-content`);



        return (
            <AntModal
                footer={null}
                width={width}
                visible={visible}
                maskClosable={maskClosable}
                closable={false}
                afterClose={close}
                onCancel={close}
                onOk={close}
                className={confirmModalClasses}
                {...rest}
            >
                <div className={confirmBodyClasses} >
                    <div className={confirmTitleClasses}>{title}</div>
                    <div className={confirmContentClasses}>{content}</div>
                </div>
                {this.renderFooter()}
            </AntModal>
        )
    }
}




export default function confirm(config) {
    const div = document.createElement('div');
    document.body.appendChild(div);

    function destroy(...args) {
        const unmountResult = ReactDOM.unmountComponentAtNode(div);
        if (unmountResult && div.parentNode) {
            div.parentNode.removeChild(div);
        }
        const triggerCancel = args && args.length &&
        args.some(param => param && param.triggerCancel);
        if (config.onCancel && triggerCancel) {
            config.onCancel(...args);
        }
    }

    function render(props) {
        ReactDOM.render(<ConfirmModal {...props} />, div);
    }

    function close(...args) {
        if (IS_REACT_16) {
            render({ ...config, close, visible: false, afterClose: destroy.bind(this, ...args) });
        } else {
            destroy(...args);
        }
    }

    render({ ...config, visible: true, close });

    return {
        destroy: close,
    };
}



