import React, { Component } from 'react';
import { Modal as AntModal } from "antd";
import classNames from "classnames";
import PropTypes from "prop-types";
import confirm from './confirm';
import Notice from './notice';

const noop = () =>{}; 
class Modal extends Component {

    static propTypes = {
        prefixCls: PropTypes.string,
        visible: PropTypes.bool,
        width: PropTypes.number,
        title: PropTypes.oneOfType([PropTypes.string, PropTypes.object]),
        maskClosable: PropTypes.bool,
        cancelText: PropTypes.oneOfType([PropTypes.string, PropTypes.object]),
        okText: PropTypes.oneOfType([PropTypes.string, PropTypes.object]),
        onOk: PropTypes.func,
        onCancel: PropTypes.func,
        className: PropTypes.string,
        style: PropTypes.object,
        children: PropTypes.any,
        getContainer: PropTypes.func
    }

    static defaultProps = {
        prefixCls: "fl",
        visible: false,
        title: "",
        width: 444,
        maskClosable: true,
        cancelText: "取消",
        okText: "保存",
        onOk: noop,
        onCancel: noop,
        className: "",
        style: {},
        children: null,
    }

    createContainer = () => {
        const { getContainer, wrapClass } = this.props;
        const div  = document.createElement('div');
        div.className = wrapClass || '';
        const node = getContainer();
        node.appendChild(div);
        return div;

    }


    render() {
        const { prefixCls, visible, title, width, maskClosable,
            cancelText, okText, getContainer, wrapClass,
            onOk, onCancel, children, className, ...rest } = this.props;
        const modalClasses = classNames(prefixCls, `${prefixCls}-modal`, className);
        const headerClasses = classNames(prefixCls, `${prefixCls}-modal-header`);
        const cancelBtnClasses = classNames(prefixCls, `${prefixCls}-cancel-btn`);
        const okBtnClasses = classNames(prefixCls, `${prefixCls}-ok-btn`);
        const titleClasses = classNames(prefixCls, `${prefixCls}-title`);
        return (
            <AntModal
                visible={visible}
                width={width}
                onOk={onOk}
                onCancel={onCancel}
                footer={null}
                maskClosable={maskClosable}
                closable={false}
                className={modalClasses}
                getContainer={getContainer && this.createContainer}
                {...rest}
            >
                <div className={headerClasses}>
                    <div className={cancelBtnClasses} onClick={onCancel}>{cancelText}</div>
                    <div className={titleClasses}>{title}</div>
                    <div className={okBtnClasses} onClick={onOk}>{okText}</div>
                </div>
                {children}
            </AntModal>
        )
    }
}


Modal.confirm = function (props) {
    return confirm({ ...props, type: "confirm" });
};

Modal.info = function (props) {
    return confirm({ ...props, type: "info" });
};


Modal.success = (props) => {
    Notice.Instance(Object.assign({ type: "success", transitionName: 'fade' }, props));
}


Modal.error = (props) => {
    Notice.Instance(Object.assign({ type: "error", transitionName: 'fade' }, props));
}

Modal.warn = (props) => {
    Notice.Instance(Object.assign({ type: "warn", transitionName: 'fade' }, props));
}

Modal.loading = (props) => {
    Notice.Instance(Object.assign({ type: "jiazaizhong", spin:true, transitionName: 'fade' }, props));
}

export default Modal;



