import React, { Component } from 'react';
import PropTypes from 'prop-types';
import classNames from "classnames";
import {Icon as Ic } from "antd";

export default class Icon extends Component {
    static propTypes = {
        fl:PropTypes.bool,
    }

    static defaultProps = {
        fl:false,
    }

    render() {
        const { fl, ...rest } = this.props;
        if(!fl) return <Ic {...rest} />
        
        const { type, className = '', spin, ..._rest } = rest;
        const classes = classNames({
            "flicon": true,
            'anticon-spin': !!spin || type === 'loading',
            [`fl-icon-${type}`]: true,
        }, className);
        return <i {..._rest} className={classes} />;
    }
}



