import React, { Component } from "react";
import PropTypes from "prop-types";
import classNames from "classnames";
import Icon from "../icon";

export default class Spin extends Component {
	static propTypes = {
	    size: PropTypes.oneOf(["small", "default", "large"]),
	    block: PropTypes.bool,
	    loading: PropTypes.bool,
	    children: PropTypes.any,
	    prefixCls: PropTypes.string,
	    tip: PropTypes.string,
	    indicator: PropTypes.element,
	};

	static defaultProps = {
	    loading: true,
	    children: null,
	    prefixCls: "fl",
	    tip: "正在载入…",
	    size: "default",
	    block: false,
	    indicator: <Icon fl type="jiazaizhong" spin />
	};

	isNestedPattern() {
	    return !!(this.props && this.props.children);
	}

	render() {
	    const { size, loading, tip, prefixCls, block, indicator, className, children, ...rest } = this.props;

	    const spinClasses = classNames(prefixCls, `${prefixCls}-spin`, `${prefixCls}-spin-${size}`, className);

	    const iconClasses = classNames(`${prefixCls}-spin-text`, {
	        [`${prefixCls}-spin-text-inline`]: !block,
	        [`${prefixCls}-spin-text-block`]: block,
	    });

	    const { className: indicatorCls, ...indicatorRest } = indicator.props;
	    const _indicator = React.cloneElement(indicator, {
	        className: classNames(`${prefixCls}-spin-icon`, { [`${prefixCls}-spin-icon-block`]: block }, indicatorCls),
	        ...indicatorRest,
	    })

	    const spinElement = (
	        block?
	            <div {...rest} className={spinClasses} >
	                {_indicator}
	                {tip ? <div className={iconClasses}>{tip}</div> : null}
	            </div>
	            :
	            <div {...rest} className={spinClasses} >
	                {tip ? <div className={iconClasses}>{tip}</div> : null}
	                {_indicator}
	            </div>
	    );

	    if (this.isNestedPattern()) {
	        return (
	            <div className={`${prefixCls}-spin-nested-container`}>
	                {loading && <div className={`${prefixCls}-spin-mask`}>{spinElement}</div>}
	                {this.props.children}
	            </div>
	        )
	    }
	    return spinElement

	}
}



