import React, { Component } from 'react';
import PropTypes from 'prop-types';
import classNames from "classnames";
import { Popover } from "antd";
import { Scrollbars } from 'react-custom-scrollbars';
import Icon from "../icon";

const noop = () => { };
/**
 * value是否受控
 */
const isValueControlled = (props) => {
    return Object.prototype.hasOwnProperty.call(props, "value")
}

export default class PopoverSelect extends Component {
    static propTypes = {
        type: PropTypes.oneOf(["radio", "select"]),// radio 为单选带选中标示，select 为普通选择
        prefixCls: PropTypes.string,
        className: PropTypes.string,
        children: PropTypes.node.isRequired,
        options: PropTypes.array.isRequired,
        onSelect: PropTypes.func,// 选中回调
        defaultValue: PropTypes.any,
        trigger: PropTypes.string,
        placement: PropTypes.string,
    }

    static defaultProps = {
        prefixCls: "fl",
        className: null,
        type: "select",
        onSelect: noop,
        defaultValue: null,
        trigger: "click",
        placement: "bottom",
    }

    constructor(props) {
        super(props);
        this.state = {
            value: props.defaultValue,
        }
    }

    getValue = () => {
        if (isValueControlled(this.props)) {
            return this.props.value;
        }
        return this.state.value;
    }

    setValue = (v) => {
        if (!isValueControlled(this.props)) {
            this.setState({
                value: v,
            })
        }
    }

    handleClick = (v) => {
        const { type, onSelect } = this.props;
        this.popover.refs.tooltip.onVisibleChange(false);
        onSelect(v);
        if (type === "radio") {
            this.setValue(v);
        }
    }

    renderContent = () => {
        const { options,type } = this.props;
        return options.map((v,i) => {
            if (Array.isArray(v)) {
                return (
                    <SelectGroup key={`${i}-group`}>
                        {
                            v.map(w => <SelectItem key={w.value} prefix={w.prefix} img={w.img} text={w.name} value={w.value} checked={type === "select" ? null : w.value === this.getValue()} onClick={e => this.handleClick(e)} />)
                        }
                    </SelectGroup>
                )
            }

            return (
                <SelectItem key={v.value} prefix={v.prefix} img={v.img} text={v.name} value={v.value} onClick={e => this.handleClick(e)} checked={type === "select" ? null : v.value === this.getValue()} />
            )
        })
    }


    render() {
        const { prefixCls, overlayClassName, className, children, title, onSelect, value, defaultValue,options, ...rest } = this.props;
        return (
            <Popover
                {...rest}
                ref={v => {this.popover = v}}
                overlayClassName={classNames(`${prefixCls}-popover-select`,overlayClassName)}
                title={null}
                content={
                    <div className={classNames("select-wrapper",className,{"select-item-group-style":Array.isArray(options[0])})}>
                        {title ? <div className="select-title">{title}</div> : null}
                        <Scrollbars autoHeight autoHeightMin={10} autoHeightMax={458}>
                            <div className="select-content">{this.renderContent()}</div>
                        </Scrollbars>
                    </div>
                }
            >
                {
                    children
                }
            </Popover>
        )
    }
}

const SelectItem = ({ prefix, img, value, text, checked, className, onClick = noop, ...rest }) => {
    const renderPrfix = () => {
        if (img === undefined) {
            return prefix;
        }
        return <img className="select-item-img" src={img} alt="" />
    }
    return (
        <div {...rest} onClick={() => onClick(value)} className={classNames("select-item", className)}>
            <div className="select-item-inner">
                <div className="select-item-text-container">
                    {renderPrfix()}
                    <span className="select-item-text">
                        {
                            text
                        }
                    </span>
                </div>
                {
                    checked ? <Icon className="select-item-check" type="check" /> : null
                }

            </div>
        </div >
    )
}
SelectItem.defaultProps = {
    prefix: null,
    checked: false,
}
SelectItem.propTypes = {
    prefix: PropTypes.element,
    text: PropTypes.node.isRequired,
    checked: PropTypes.bool
}

const SelectGroup = ({ children, className }) => {
    return <div className={classNames("select-item-group", className)}>
        {
            children
        }
    </div>
}

SelectGroup.defaultProps = {
    className: null,
}

SelectGroup.propTypes = {
    children: PropTypes.node.isRequired,
    className: PropTypes.string
}



